import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const d=JSON.parse('{"title":"Helm部署K8S时Secret大小超过1MB的问题","description":"","frontmatter":{"title":"Helm部署K8S时Secret大小超过1MB的问题","date":"2023-06-12","categories":["云原生","Kubernetes"],"tags":["Kubernetes"]},"headers":[],"relativePath":"云原生/Helm部署K8S时Secret大小超过1MB的问题.md","filePath":"云原生/Helm部署K8S时Secret大小超过1MB的问题.md"}'),n={name:"云原生/Helm部署K8S时Secret大小超过1MB的问题.md"};function l(p,s,h,r,k,c){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="helm部署k8s时secret大小超过1mb的问题" tabindex="-1">Helm部署K8S时Secret大小超过1MB的问题 <a class="header-anchor" href="#helm部署k8s时secret大小超过1mb的问题" aria-label="Permalink to &quot;Helm部署K8S时Secret大小超过1MB的问题&quot;">​</a></h1><h2 id="一现象" tabindex="-1">一、现象 <a class="header-anchor" href="#一现象" aria-label="Permalink to &quot;一、现象&quot;">​</a></h2><p>在使用Helm部署K8S应用时，发现<code>helm install</code>指令报错，报错内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: create: failed to create: Secret &quot;sh.helm.release.v1.xxxxxx-xxxxxxxx.v1&quot; is invalid:</span></span>
<span class="line"><span>data: Too long: must have at most 1048576 bytes</span></span></code></pre></div><p>上述报错信息表明，在Helm部署K8S创建Secret时，其内容超过了1048576 bytes（即1MB），导致部署失败。基于上述报错，可能需要考虑以下几点：</p><ul><li>Helm使用Secret的原因</li><li>1MB上限的根源</li><li>Helm中Secret的内容</li></ul><h2 id="二排查过程" tabindex="-1">二、排查过程 <a class="header-anchor" href="#二排查过程" aria-label="Permalink to &quot;二、排查过程&quot;">​</a></h2><h3 id="一helm使用secret的原因以及1mb上限的根源" tabindex="-1">（一）Helm使用Secret的原因以及1MB上限的根源 <a class="header-anchor" href="#一helm使用secret的原因以及1mb上限的根源" aria-label="Permalink to &quot;（一）Helm使用Secret的原因以及1MB上限的根源&quot;">​</a></h3><p>根据<a href="https://helm.sh/zh/docs/" target="_blank" rel="noreferrer">Helm官方文档</a>，Helm在部署时会默认<a href="https://helm.sh/zh/docs/topics/advanced/#%E5%90%8E%E7%AB%AF%E5%AD%98%E5%82%A8" target="_blank" rel="noreferrer">使用Secret保存Helm版本信息</a>，该版本信息包含了位于HelmChart目录下的所有数据（包括挂载文件等内容），这里的Secret也可以根据配置替换为ConfigMap或PostgreSQL存储。</p><p>同时，根据<a href="https://kubernetes.io/zh-cn/docs/home/" target="_blank" rel="noreferrer">K8S官方文档</a>，K8S对Secret大小有所<a href="https://kubernetes.io/zh-cn/docs/concepts/configuration/secret/#restriction-data-size" target="_blank" rel="noreferrer">限制</a>，其要求Secret不能大于1MB。</p><p>综上，Helm使用Secret的原因是：保存Helm版本信息。1MB上限的根源是：K8S本身的限制，与Helm没有关系。</p><p>针对这种情况，Helm提供了一种解决方案：使用PostgreSQL存储Helm版本信息，这种方案对Helm版本信息大小没有限制，允许大小超过1MB。但单独为Helm部署一套数据库成本相对较高，减少Secret中非必要的内容可能更符合K8S的规范。对此，需要先查看Helm中的Secret存在哪些内容，具体详见<a href="#二helm中secret的内容">下文</a>。</p><h3 id="二helm中secret的内容" tabindex="-1">（二）Helm中Secret的内容 <a class="header-anchor" href="#二helm中secret的内容" aria-label="Permalink to &quot;（二）Helm中Secret的内容&quot;">​</a></h3><p>首先，使用<code>kubectl describe</code>查看secret的概要信息：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 查看所有Secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh.helm.release.v1.xxxxxx-xxxxxxxx.v1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 查看特定Secret的描述信息</span></span></code></pre></div><blockquote><p>由于前面Helm创建Secret报错，这里可以找一个类似的Secret查看里面的内容。</p></blockquote><p>结果如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name:         sh.helm.release.v1.xxxxxx-xxxxxxxx.v1</span></span>
<span class="line"><span>Namespace:    xxxxxx</span></span>
<span class="line"><span>Labels:       modifiedAt=1680513692</span></span>
<span class="line"><span>              name=xxxxxx-xxxxxxxx</span></span>
<span class="line"><span>              owner=helm</span></span>
<span class="line"><span>              status=deployed</span></span>
<span class="line"><span>              version=1</span></span>
<span class="line"><span>Annotations:  &lt;none&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Type:  helm.sh/release.v1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Data</span></span>
<span class="line"><span>====</span></span>
<span class="line"><span>release:  999999 bytes</span></span></code></pre></div><p>可以看到，这个Secret里面Data的内容大小是999999 bytes，但其具体内容并没有打印（<code>kubectl describe ConfigMap</code>是可以直接显示配置内容的）。对此，需要使用下述命令查看Secret的配置内容：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh.helm.release.v1.xxxxxx-xxxxxxxx.v1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&quot;{ .data.release }&quot;</span></span></code></pre></div><p>该命令会打印加密过后的配置内容，Helm采取gzip与base64的方式加密（参见此条<a href="https://github.com/helm/helm/issues/11464" target="_blank" rel="noreferrer">helm github issue</a>讨论记录）。对此，需要使用以下指令对配置内容进行解密：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh.helm.release.v1.xxxxxx-xxxxxxxx.v1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&quot;{ .data.release }&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gunzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">secret.json</span></span></code></pre></div><p>该命令会将加密后的内容经过两次base64解密（第一次是K8S的base64，第二次是Helm的base64），随后再使用gunzip完成解压，最终输出格式如下所示：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xxxxxx-xxxxxxxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;chart&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">                &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.helmignore&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">                &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            }</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            // 其它文件略</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><blockquote><p>data中的内容也是基于base64加密的，使用<code>base64 --decode</code>解密即可。</p></blockquote><p>通过分析上述内容，发现有很多非必要的文件都被打入到了HelmChart Secret中，在<code>.helmignore</code>文件中加入不必要的文件路径后，问题最终得到解决。</p><h2 id="三结论" tabindex="-1">三、结论 <a class="header-anchor" href="#三结论" aria-label="Permalink to &quot;三、结论&quot;">​</a></h2><p>Helm部署时使用Secret保存版本信息，同时，K8S限制了Secret的内容不能大于1MB。因此，有以下两种解决方案:</p><ol><li>将Helm中的存储系统由Secret替换为PostgreSQL，因为PostgreSQL没有存储大小的限制。该方案引入了新的数据库组件，改造成本相对较高，非必要不太建议使用。</li><li>通过<code>base64</code>和<code>gunzip</code>获取secret中的内容，找到非必要的文件，并将其路径添加到<code>.helmignore</code>文件中，以避免将其打入HelmChart包。该方案改动较小，推荐使用。如果确实所有文件都必须打入HelmChart，且大小超过1MB，也可考虑采用上述PostgreSQL方案。</li></ol><blockquote><p>参考文档</p></blockquote><ul><li><a href="https://helm.sh/zh/docs/" target="_blank" rel="noreferrer">Helm官方文档</a></li><li><a href="https://kubernetes.io/zh-cn/docs/home/" target="_blank" rel="noreferrer">K8S官方文档</a></li><li><a href="https://dbafromthecold.com/2020/08/10/decoding-helm-secrets/" target="_blank" rel="noreferrer">Decoding Helm Secrets</a></li></ul>`,31)])])}const g=e(n,[["render",l]]);export{d as __pageData,g as default};
